package com.loyu3c.rental;
import org.json.*;import java.time.*;import java.util.*;
/** Allowlist projections: never send an entire catalog to a sharing endpoint. */
public final class SharedReports {
    private static final String[] MONEY={"billed","paid","remaining","cash","topups","expenses","held","net"};
    private static JSONObject summary(JSONObject source)throws JSONException{JSONObject r=new JSONObject();for(String k:MONEY)r.put(k,source.optLong(k));r.put("invoiceCount",source.optInt("invoiceCount"));return r;}
    public static JSONObject owner(JSONObject b,YearMonth month,String ownerId)throws JSONException{
        Owners.requireComplete(b,ownerId);JSONObject all=OwnerReport.build(b,month),total=summary(new JSONObject());JSONArray properties=new JSONArray(),units=new JSONArray(),accounts=new JSONArray(),tenants=new JSONArray();Set<String> pids=new HashSet<>();
        JSONArray raw=all.getJSONArray("properties");for(int i=0;i<raw.length();i++){JSONObject p=raw.getJSONObject(i);if(!ownerId.equals(Owners.propertyOwner(b,p.getString("id"))))continue;pids.add(p.getString("id"));JSONObject safe=summary(p).put("id",p.getString("id")).put("name",p.getString("name"));properties.put(safe);for(String key:MONEY)total.put(key,Math.addExact(total.getLong(key),p.getLong(key)));total.put("invoiceCount",total.getInt("invoiceCount")+p.optInt("invoiceCount"));}
        JSONArray allUnits=Owners.rows(b,"units"),leases=Owners.rows(b,"leases");LocalDate asOf=month.atEndOfMonth().isAfter(LocalDate.now(ZoneId.of("Asia/Taipei")))?LocalDate.now(ZoneId.of("Asia/Taipei")):month.atEndOfMonth();
        for(int i=0;i<allUnits.length();i++){JSONObject u=allUnits.getJSONObject(i);if(!pids.contains(u.getString("propertyId")))continue;JSONObject current=Occupancy.current(allUnits,leases,u,asOf);JSONObject r=new JSONObject().put("propertyId",u.getString("propertyId")).put("code",u.getString("code")).put("enabled",RentalUnits.enabled(u)).put("status",Occupancy.status(allUnits,leases,u,asOf));if(current!=null)r.put("start",current.getString("start")).put("end",current.optString("terminatedOn",current.getString("end")));units.put(r);}
        for(int i=0;i<properties.length();i++){JSONObject p=properties.getJSONObject(i);int rented=0,vacant=0,disabled=0;for(int j=0;j<units.length();j++){JSONObject u=units.getJSONObject(j);if(!p.getString("id").equals(u.getString("propertyId")))continue;if(!u.getBoolean("enabled"))disabled++;else if(u.getString("status").startsWith("出租中"))rented++;else vacant++;}p.put("rented",rented).put("vacant",vacant).put("disabled",disabled);}
        JSONArray tr=all.getJSONArray("tenants");for(int i=0;i<tr.length();i++){JSONObject r=tr.getJSONObject(i);if(pids.contains(r.getString("propertyId")))tenants.put(summary(r).put("id",r.getString("id")).put("propertyId",r.getString("propertyId")).put("code",r.getString("code")).put("name","").put("status",r.getString("status")));}
        JSONArray bank=Owners.rows(b,"accounts");for(int i=0;i<bank.length();i++){JSONObject a=bank.getJSONObject(i);if(!ownerId.equals(a.optString("ownerId")))continue;boolean safe=Owners.accountSafe(b,a)&&!month.atEndOfMonth().isBefore(LocalDate.parse(a.getString("start")));long balance=safe?Bookkeeping.balance(a,month.atEndOfMonth().toString(),Owners.rows(b,"receipts"),Owners.rows(b,"expenses"),Owners.rows(b,"transfers"),Owners.rows(b,"deposits"),Owners.rows(b,"settlements")):0;accounts.put(new JSONObject().put("name",a.getString("name")).put("type",a.getString("type")).put("balance",balance).put("withheld",!safe));}
        return new JSONObject().put("month",month.toString()).put("asOf",asOf.toString()).put("total",total.put("name","此房東不動產")).put("properties",properties).put("units",units).put("tenants",tenants).put("accounts",accounts);
    }
    public static JSONObject tenant(JSONObject b,String leaseId)throws JSONException{
        JSONObject lease=Owners.find(Owners.rows(b,"leases"),leaseId);if(lease==null)throw new IllegalArgumentException("租約不存在");JSONArray invoices=Owners.rows(b,"invoices"),receipts=Owners.rows(b,"receipts"),bills=new JSONArray(),payments=new JSONArray(),deposits=new JSONArray();Set<String> ids=new HashSet<>();
        for(int i=0;i<invoices.length();i++){JSONObject bill=invoices.getJSONObject(i);if(!leaseId.equals(bill.getString("leaseId")))continue;ids.add(bill.getString("id"));long paid=Ledger.paid(bill.getString("id"),receipts);JSONObject r=new JSONObject();for(String key:new String[]{"month","kind","due","rent","water","electricity"})r.put(key,bill.get(key));r.put("total",Ledger.total(bill)).put("paid",paid).put("remaining",Ledger.total(bill)-paid);for(String key:new String[]{"previous","current","rate","periodStart","periodEnd"})if(bill.has(key))r.put(key,bill.get(key));bills.put(r);}
        for(int i=0;i<receipts.length();i++){JSONObject r=receipts.getJSONObject(i);if(!leaseId.equals(r.getString("leaseId")))continue;JSONArray parts=r.getJSONArray("allocations"),allocations=new JSONArray();for(int j=0;j<parts.length();j++){JSONObject part=parts.getJSONObject(j);if(!ids.contains(part.getString("invoiceId")))throw new IllegalArgumentException("租客收款分配關聯錯誤");JSONObject bill=Owners.find(invoices,part.getString("invoiceId"));allocations.put(new JSONObject().put("month",bill.getString("month")).put("kind",bill.getString("kind")).put("amount",part.getLong("amount")));}payments.put(new JSONObject().put("date",r.getString("date")).put("kind",r.optBoolean("cash",true)?"實際收款":"抵付").put("amount",r.getLong("amount")).put("unallocated",r.getLong("amount")-Ledger.allocated(r)).put("allocations",allocations));}
        JSONArray settlements=Owners.rows(b,"settlements");for(int i=0;i<settlements.length();i++){JSONObject settlement=settlements.getJSONObject(i);if(!leaseId.equals(settlement.getString("leaseId")))continue;JSONArray extra=settlement.getJSONArray("payments");for(int j=0;j<extra.length();j++){JSONObject payment=extra.getJSONObject(j);payments.put(new JSONObject().put("date",payment.getString("date")).put("kind","結算補繳實收").put("amount",payment.getLong("amount")).put("unallocated",0).put("allocations",new JSONArray()));}}
        JSONArray ds=Owners.rows(b,"deposits");for(int i=0;i<ds.length();i++){JSONObject d=ds.getJSONObject(i);if(leaseId.equals(d.getString("leaseId"))&&!d.optBoolean("void"))deposits.put(new JSONObject().put("date",d.getString("date")).put("kind",d.getString("kind")).put("amount",d.getLong("amount")));}
        JSONObject terms=new JSONObject().put("code",lease.getString("unitCodeSnapshot")).put("start",lease.getString("start")).put("end",lease.getString("end")).put("terminatedOn",lease.optString("terminatedOn")).put("pricing",RentTerms.pricing(lease)).put("rent",lease.getLong("rent")).put("cycle",lease.getString("cycle")).put("deposit",lease.getLong("deposit"));
        return new JSONObject().put("terms",terms).put("bills",bills).put("payments",payments).put("depositSummary",Deposits.summary(leaseId,ds)).put("deposits",deposits).put("hasContract",!lease.optString("contractFile").isEmpty());
    }
}
